<?php $title="New Sale";require "includes/header.php";$cs=$conn->query("SELECT id,name FROM customers");$bs=$conn->query("SELECT id,name,price FROM bicycles WHERE stock>0");if($_SERVER["REQUEST_METHOD"]==="POST"){$cid=(int)$_POST["customer_id"];$bid=(int)$_POST["bicycle_id"];$q=(int)$_POST["qty"];$b=$conn->query("SELECT price FROM bicycles WHERE id=$bid")->fetch_assoc();$amt=$b["price"]*$q;$inv="SC-".date("YmdHis");$s=$conn->prepare("INSERT INTO sales(invoice_no,customer_id,bicycle_id,qty,amount,payment,sale_date) VALUES(?,?,?,?,?,?,CURDATE())");$s->bind_param("siidss",$inv,$cid,$bid,$q,$amt,$_POST["payment"]);$s->execute();$conn->query("UPDATE bicycles SET stock=stock-$q WHERE id=$bid");go("sales.php");}?><div class="card"><h2>New Sale</h2><form method="post"><label>Customer</label><select name="customer_id"><?php while($x=$cs->fetch_assoc()):?><option value="<?=$x["id"]?>"><?=e($x["name"])?></option><?php endwhile;?></select><label>Bicycle</label><select name="bicycle_id"><?php while($x=$bs->fetch_assoc()):?><option value="<?=$x["id"]?>"><?=e($x["name"])?> — <?=money($x["price"])?></option><?php endwhile;?></select><label>Quantity</label><input name="qty" type="number" min="1" value="1"><label>Payment</label><select name="payment"><option>UPI</option><option>Cash</option><option>Card</option><option>EMI</option></select><button class="btn primary">Create Sale</button></form></div><?php require "includes/footer.php";?>